// news-image-20261125 — V3 "Four Fronts" (grid 2x2).
//
// The entry image is a finished JPEG generated by Milku (Generate Image).
// This program only copies its bytes to the output file the gate reads:
// $MAKEFUN_OUTPUT_DIR/entry.png. The name stays entry.png even though the
// bytes are JPEG — the rules tell PNG from JPEG by the first bytes.
// Deterministic: the same bytes on every run, no network, no clock.
// Gate: output at most 1 MiB and at most 1024x1024 pixels; image.jpg is
// 258,600 bytes at 1024x1024 (the generated 1600x1600 file resized once for
// format compliance), so it passes both limits with room to spare.
import { copyFileSync, mkdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const repoDir = dirname(fileURLToPath(import.meta.url));
const source = join(repoDir, "image.jpg");
const outDir = process.env.MAKEFUN_OUTPUT_DIR || "/output";
mkdirSync(outDir, { recursive: true });
copyFileSync(source, join(outDir, "entry.png"));
console.log("wrote entry.png from image.jpg");
